<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$pageTitle='Activities';
$filterDate=(string)($_GET['date']??date('Y-m-d'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$filterDate)) $filterDate=date('Y-m-d');
$stmt=$pdo->prepare('SELECT id,title,category,activity_date,start_time,end_time,notes FROM activities WHERE activity_date=? ORDER BY start_time ASC');$stmt->execute([$filterDate]);$items=$stmt->fetchAll();
$all=$pdo->query('SELECT COUNT(*) total, COUNT(DISTINCT activity_date) days FROM activities')->fetch();
$coverFiles = glob(__DIR__ . '/../uploads/cover/cover.{jpg,jpeg,png,webp}', GLOB_BRACE) ?: [];
$activitiesCoverUrl = $coverFiles ? '../uploads/cover/' . basename($coverFiles[0]) : '';
require __DIR__ . '/../includes/header.php';
?>
<section class="hero-panel compact-hero activities-hero"<?= $activitiesCoverUrl !== '' ? ' style="background-image: url(' . e($activitiesCoverUrl) . ');"' : '' ?>>
<div class="hero-shade activities-hero-shade"></div><div class="activities-hero-copy"><p class="eyebrow">PLAN YOUR TIME</p><h1>Activities<span class="gold-period">.</span></h1><p class="hero-description">Organise your daily activities, schedule and notes in one place.</p></div>
<form class="cover-upload-form" action="<?= e(app_url('actions/cover-upload.php')) ?>" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="return_to" value="pages/activities.php"><label class="btn btn-outline btn-small" for="activitiesCoverInput">▧ Change cover photo</label><input id="activitiesCoverInput" type="file" name="cover" accept="image/jpeg,image/png,image/webp" required onchange="if(this.form.dataset.submitting!=='1'){this.form.dataset.submitting='1';this.form.submit();}"></form></section>
<div class="stats-grid"><article class="stat-card"><span class="stat-label">Activities on selected day</span><div class="stat-value"><?= count($items) ?><span class="stat-unit"> items</span></div></article><article class="stat-card"><span class="stat-label">All recorded activities</span><div class="stat-value"><?= (int)$all['total'] ?><span class="stat-unit"> total</span></div></article><article class="stat-card"><span class="stat-label">Days with plans</span><div class="stat-value"><?= (int)$all['days'] ?><span class="stat-unit"> days</span></div></article></div>
<section class="content-panel"><div class="section-heading"><div><p class="eyebrow">DAILY SCHEDULE</p><h2>Choose a date</h2></div><form method="get" class="inline-filter"><input type="date" name="date" value="<?= e($filterDate) ?>"><button class="btn btn-outline" type="submit">View day</button></form></div>
<div class="section-heading"><div><p class="eyebrow">YOUR PLAN</p><h2><?= e(date('l, d F Y',strtotime($filterDate))) ?></h2></div><button class="btn btn-gold" type="button" data-open-modal="activityCreateModal">＋ Add activity</button></div>
<?php if(!$items): ?><div class="empty-state"><div class="empty-icon">◷</div><h3>No activities for this date</h3><p>Add something you want to make time for.</p></div><?php else: ?>
<div class="activity-manager-list"><?php foreach($items as $it): ?><article class="manager-card"><div class="manager-time"><?= e(date('g:i A',strtotime($it['start_time']))) ?><?php if($it['end_time']): ?><small>to <?= e(date('g:i A',strtotime($it['end_time']))) ?></small><?php endif; ?></div><div class="manager-main"><span class="category-pill"><?= e($it['category']) ?></span><h3><?= e($it['title']) ?></h3><?php if($it['notes']): ?><p><?= nl2br(e($it['notes'])) ?></p><?php endif; ?><details class="inline-edit"><summary>Edit activity</summary><form action="<?= e(app_url('actions/activity-edit.php')) ?>" method="post" class="form-stack"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><input type="hidden" name="return_to" value="activities.php?date=<?= e($filterDate) ?>"><label>Activity name<input name="title" maxlength="160" value="<?= e($it['title']) ?>" required></label><div class="form-row"><label>Category<select name="category"><?php foreach(['Personal','Work','Fitness','Gaming','Entertainment','Rest','Errands'] as $c): ?><option <?= $it['category']===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach; ?></select></label><label>Date<input type="date" name="activity_date" value="<?= e($it['activity_date']) ?>" required></label></div><div class="form-row"><label>Start time<input type="time" name="start_time" value="<?= e(substr($it['start_time'],0,5)) ?>" required></label><label>End time<input type="time" name="end_time" value="<?= e(substr((string)$it['end_time'],0,5)) ?>"></label></div><label>Notes<textarea name="notes" rows="2" maxlength="1000"><?= e((string)$it['notes']) ?></textarea></label><button class="btn btn-gold" type="submit">Save changes</button></form></details></div><form action="<?= e(app_url('actions/activity-remove.php')) ?>" method="post" data-confirm="Remove this activity?" class="manager-remove"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><input type="hidden" name="return_to" value="activities.php?date=<?= e($filterDate) ?>"><button class="btn btn-outline danger-action" type="submit">Remove</button></form></article><?php endforeach; ?></div><?php endif; ?></section>
